function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToList;
  sorted.Sort;
  for var i := 0 to sorted.Count - 2 do
    if sorted[i] + sorted[i + 1] <= threshold then
    begin
      Result := True;
      exit;
    end;
  Result := False;
end;

begin
end.




function SeparateParenGroups(parenString: string): array of string;
begin
  var groups := new List<string>;
  var stack := new Stack<char>;

  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = ' ' then
      continue;

    if parenString[i] = '(' then
      stack.Push(parenString[i])
    else
    begin
      if stack.Count > 0 then
        stack.Pop;
      else
        stack.Push(parenString[i]);
    end;

    if stack.Count = 0 then
    begin
      var group := '';
      while parenString[i] <> '(' do
      begin
        group += parenString[i];
        i += 1;
      end;
      groups.Add(group);
    end;
  end;

  Result := groups.ToArray;
end;

begin
end.




