function ParseNestedParens(parenString: string): array of integer;
begin
  var levels := new List<integer>;
  var stack := new Stack<integer>;

  foreach var ch in parenString do
  begin
    if ch = '(' then
    begin
      stack.Push(levels.Count);
      levels.Add(0);
    end
    else if ch = ')' then
    begin
      var top := stack.Pop;
      levels[top] := levels.Count - 1;
    end;
  end;

  Result := levels.ToArray;
end;

begin
end.




