function MakePalindrome(str: string): string;
begin
  var s := str;
  var n := s.Length;
  for var i := n - 1 downto 0 do
  begin
    if IsPalindrome(s.Substring(0, i)) then
    begin
      var suffix := s.Substring(i);
      var prefix := s.Substring(0, i);
      var reverseSuffix := ReverseString(suffix);
      var palindrome := prefix + reverseSuffix;
      Result := palindrome;
      exit;
    end;
  end;
  Result := s;
end;

begin
end.




