function FindClosestElements(numbers: array of real): (real, real);
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  var minDiff := sorted[1] - sorted[0];
  var minNum1 := sorted[0];
  var minNum2 := sorted[1];
  for var i := 2 to sorted.Length - 1 do
  begin
    var diff := sorted[i] - sorted[i-1];
    if diff < minDiff then
    begin
      minDiff := diff;
      minNum1 := sorted[i-1];
      minNum2 := sorted[i];
    end;
  end;
  Result := (minNum1, minNum2);
end;

begin
end.




