function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := False;
    exit;
  end;

  if n <= 3 then
  begin
    Result := True;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := False;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := False;
      exit;
    end;
    i += 6;
  end;

  Result := True;
end;

begin
end.



function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var eps := 1e-10;
  var a := 0.0;
  var b := 1.0;
  while b - a > eps do
  begin
    var c := (a + b) / 2;
    if Poly(xs, c) * Poly(xs, a) < 0 then
      b := c
    else
      a := c;
  end;
  Result := a;
end;

begin
end.




