function Modp(n, p: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
  begin
    if n < 0 then
      n := -n;
    if p = 0 then
    begin
      if n = 0 then
        Result := 1
      else
        Result := 0;
    end
    else
    begin
      var res := 1;
      for var i := 1 to n do
        res := (res * res) mod p;
      Result := res;
    end;
  end;
end;

begin
end.



function EncodeShift(s : string): string;
{ returns encoded string by shifting every character by 5 in the alphabet. }
begin
  Result := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    Result += Chr(((Ord(ch) + 5 - Ord('a')) mod 26) + Ord('a'));
  end;
end;
function DecodeShift(s: string): string;
begin
  var decoded := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    decoded += Chr((Ord(ch) - Ord('a') - 5) mod 26 + Ord('a'));
  end;
  Result := decoded;
end;

begin
end.




