  var remaining := new List<integer>;

  foreach var num in lst do
    remaining.Add(num);

  while remaining.Count > 0 do
  begin
    var minVal := remaining.Min;
    remaining.RemoveAt(remaining.IndexOf(minVal));
    sorted.Add(minVal);

    if remaining.Count > 0 then
    begin
      var maxVal := remaining.Max;
      remaining.RemoveAt(remaining.IndexOf(maxVal));
