  for var i := 0 to lst.Length - 1 do
    if lst[i] = smallest then
    begin
      if i = 0 then
      begin
        Result := integer.MaxValue;
        exit;
      end;

      if i = lst.Length - 1 then
      begin
        Result := sorted[0];
        exit;
      end;

      Result := sorted[i + 1];
      exit;
    end;

  Result := integer.MaxValue;
end;

