    sign := -1;

  var absA := Abs(a);
  var absB := Abs(b);
  var product := 0;

  for var i := 0 to absB - 1 do
  begin
    var temp := absA;
    while temp > 0 do
    begin
      if (temp mod 10) = absB then
        product += absA;
      temp := temp div 10;
    end;
  end;

  Result := sign * product;
end;

