function Histogram(test: string): Dictionary<string, integer>;
begin
  var words := test.Split(' ');
  var histogram := new Dictionary<string, integer>;
  var maxCount := 0;

  foreach var word in words do
  begin
    if histogram.ContainsKey(word) then
      histogram[word] += 1
    else
      histogram[word] := 1;

    if histogram[word] > maxCount then
      maxCount := histogram[word];
  end;

  var keys := histogram.Keys.ToList;
  var res := Lst(keys.Where(k -> histogram[k] = maxCount));

  if res.Count > 0 then
    Result := res.ToDictionary(k -> k, k -> histogram[k])
  else
    Result := new Dictionary<string, integer>;
end;

begin
end.




