function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var dp := new integer[m+1][n+1];
  var bucket := new integer[m+1][n+1];

  for var i := 1 to m do
    for var j := 1 to n do
    begin
      if grid[i-1][j-1] = 0 then
      begin
        dp[i][j] := dp[i-1][j] + dp[i][j-1];
        bucket[i][j] := bucket[i-1][j] + bucket[i][j-1];
      end;
    end;

  var ans := 0;
  for var i := 1 to m do
    for var j := 1 to n do
    begin
      if grid[i-1][j-1] = 0 then
      begin
        var bucketCount := bucket[i][j];
        var bucketSize := capacity;
        var bucketNum := 0;

        while bucketSize <= bucketCount do
        begin
          bucketNum += 1;
          bucketSize += capacity;
        end;

        ans += bucketNum;
      end;
    end;

  Result := ans;
end;

begin
end.




