  begin
    if x.Item1 < y.Item1 then
      Result := -1
    else if x.Item1 > y.Item1 then
      Result := 1
    else
    begin
      if x.Item2 < y.Item2 then
        Result := -1
      else if x.Item2 > y.Item2 then
        Result := 1
      else
        Result := 0;
    end;
  end);

  foreach var (sum, index) in sums do
    sorted.Add(nums[index]);

  Result := sorted.ToArray;
end;

