function RightAngleTriangle(a, b, c: integer): boolean;
begin
  var sides := Arr(a, b, c);
  &Array.Sort(sides);
  Result := sides[0] * sides[0] + sides[1] * sides[1] = sides[2] * sides[2];
end;

