end.




function FindMax(words: array of string): string;
begin
  var wordList := words.ToList;
  var sortedWords := wordList.OrderBy(w -> w).ToList;
  var maxWord := sortedWords[0];
  var maxCount := 0;

  foreach var word in wordList do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    if uniqueChars.Count > maxCount then
    begin
      maxCount := uniqueChars.Count;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;

begin
end.




function Eat(number, need, remaining: integer): (integer, integer);
begin
  var total := number + remaining;
  if total < need then
    Result := (total, total)
  else
    Result := (total - need, remaining - need);
end;

begin
end.




function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    if op[0] = '+' then
      res := res + operand[i]
    else if op[0] = '-' then
      res := res - operand[i]
    else if op[0] = '*' then
      res := res * operand[i]
    else if op[0] = '//' then
      res := res div operand[i]
    else if op[0] = '**' then
      res := res * operand[i]
    else
      raise new Exception('Invalid operator');
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  if s.All(c -> c.IsLetter) then
  begin
    if s.All(c -> c.IsLower) then
      Result := s.Reverse.JoinToString
    else
      Result := s.Reverse.Select(c -> c.ToUpper).JoinToString;
  end
  else
    Result := s.Reverse.JoinToString;
end;

begin
end.




